import { isFunction, isObject, isString, ShapeFlags } from "@vue/shared";
import { isTeleport } from './components/Teleport'
export const Text = Symbol('Text'); // 文本节点

export const Fragment = Symbol('Fragment')

export function isVnode(value) {
  return !!value?.__v_isVnode
}

/**
 * 判断两个节点是否相同
 * @param n1 旧节点
 * @param n2 新节点
 * @returns 
 */
export function isSameVnode(n1, n2) {
  return n1.type === n2.type && n1.key === n2.key
}

// 按位或(|), 二进制有一个为1就是1
// let a = 5 // 转换成2进制 0101
// a = a | 3 // 3的二进制是 0011 => 等同于 按位与赋值 a |= 3
// a = 7                   0101 => 7
// 按位与(&), 二进制都为1才是1
// a = a & 3 // 3的二进制是 0011 => 等同于 按位与赋值 a &= 3
// a = 1                   0001 => 1

export function createVnode(type, props, children, patchFlag?) {
  const shapeFlag = 
    isString(type) ? ShapeFlags.ELEMENT // 元素
    : isTeleport(type) ? ShapeFlags.TELEPORT // Teloport
    : isObject(type) ? ShapeFlags.STATEFUL_COMPONENT // 组件
    : isFunction(type) ? ShapeFlags.FUNCTIONAL_COMPONENT // 函数组件
    : 0;
  const vnode = {
    __v_isVnode: true,
    type,
    props,
    children,
    key: props?.key,
    el: null, // 虚拟节点对应的真实节点
    shapeFlag,
    ref: props?.ref,
    patchFlag
  }
  if (Array.isArray(children)) {
    // vnode.shapeFlag = vnode.shapeFlag | ShapeFlags.ARRAY_CHILDREN; // 虚拟节点类型
    vnode.shapeFlag |= ShapeFlags.ARRAY_CHILDREN // 简写， 按位或赋值运算符
  } else if(isObject(children)) {
    vnode.shapeFlag |= ShapeFlags.SLOTS_CHILDREN // 组件的孩子，比如插槽
  } else {
    children = String(children)
    vnode.shapeFlag |= ShapeFlags.TEXT_CHILDREN
  }
  return vnode
}

export let currentBlock = null;
export function openBlock(disableTracking) {
  if (!disableTracking) {
    currentBlock = []; // 用于收集动态节点
  }
}

export function closeBlock() {
  currentBlock = null
}

export function setupBlock(vnode) {
  vnode.dynamicChildren = currentBlock  // 当前elementBlock会收集子节点，用当前block来收集
  closeBlock();
  return vnode
}

// block 有收集虚拟节点的能力
export function createElementBlock(type, props, children, patchFlag?) {
  const vnode = createVnode(type, props, children, patchFlag);
  return setupBlock(vnode)
}

export function toDisplayString(value) {
  return isString(value) 
    ? value 
    : value === null 
    ? "" 
    : isObject(value) 
    ? JSON.stringify(value) 
    : String(value)
}

export { createVnode as createElementVNode }
